 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    private List> ans = new ArrayList<>();
    private List t = new ArrayList<>();

    public List> pathSum(TreeNode root, int targetSum) {
