struct MyStack {
    /// There could only be two status at all time
    /// 1. One contains N elements, the other is empty
    /// 2. One contains N - 1 elements, the other contains exactly 1 element
    q_1: VecDeque,
    q_2: VecDeque,
    // Either 1 or 2, originally begins from 1
    index: i32,
}

