use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

struct Node {
    key: i32,
    value: i32,
    freq: i32,
    prev: Option>>,
    next: Option>>,
}

impl Node {
    fn new(key: i32, value: i32) -> Self {
